contributes.serverHook:
onRecordAfterCreateSuccess((e) => {
  const cfg = __FACET_SETTINGS__;
  if (cfg.log) console.log(`[deadline-badge] новая запись ${e.record.id} в ${cfg.entity}`);
  e.next();
}, (__FACET_SETTINGS__).entity);

contributes.portalScript:
(() => {
  const DAYS = 3;
  window.FacetPortal?.onRender(({ root }) => {
    root.querySelectorAll('[data-date]').forEach((el) => {
      const d = new Date(el.getAttribute('data-date'));
      const left = (d.getTime() - Date.now()) / 86400000;
      if (left >= 0 && left < DAYS && !el.querySelector('.fx-soon')) {
        const b = document.createElement('span');
        b.className = 'fx-soon';
        b.textContent = document.documentElement.lang === 'en' ? 'soon' : 'скоро';
        el.appendChild(b);
      }
    });
  });
})();
